// #d9aa30282ea83831ce4afdeb — сбой start-voice-session ПОСЛЕ старта официальной попытки: «נסו שוב» повторяет ТУ ЖЕ попытку
// (тот же attempt_id, нового candidate_start_attempt нет), попытка не сгорает. Кейсы CALL-006, CALL-007.
// Переписан 22.10.2026: по исправлению #da072b отказ сервера/провайдера (503 provider_unavailable) больше НЕ даёт «נסו שוב» —
// попытка сразу technical_failure; это проверяет provider-refusal-da072b.spec.ts (CALL-031). Здесь сбой — только настоящая
// сетевая ошибка: route.abort('internetdisconnected') на start-voice-session (как CALL-033), при ней «נסו שוב» остаётся.
// Повтор на той же попытке после сетевой ошибки после #da072b вживую не перепроверялся — первый прогон в /qa-regress и есть проверка;
// если поведение разойдётся — не подгонять ожидание, сообщить пользователю.
// НЕ prod-safe: создаёт кандидата «QA-AUTO-CALL-S-…» (link_only); последний тест (@slow) ТРАТИТ официальную попытку и AI.
// Кандидат не удаляется (правило проекта).
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import {
  Candidate, TXT, createCandidateLink, candidateRow, launchCandidate, goToPractice, goToOfficialConfirm, tap,
  expectHelpPath, waitConnectingHint,
} from './support';

test.describe.configure({ mode: 'serial' });

const NETWORK_FAIL = 'לא הצלחנו להתחיל את השיחה, כנראה בגלל תקלה בחיבור לאינטרנט. בדקו את החיבור ונסו שוב.';
const VOICE = '**/functions/v1/start-voice-session';
const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-headers': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
};

let cand: Candidate | undefined;
let name = '';
const attemptIds: string[] = [];

/** start-voice-session (POST) обрывается без ответа — настоящая сетевая ошибка; candidate_start_attempt не трогаем. */
async function dropVoiceSession(page: Page) {
  await page.route(VOICE, (route) =>
    route.request().method() === 'OPTIONS' ? route.fulfill({ status: 204, headers: CORS }) : route.abort('internetdisconnected'),
  );
}

/** attempt_id каждого POST start-voice-session (и оборванного, и настоящего). */
function trackAttemptIds(page: Page) {
  page.on('request', (r) => {
    if (r.method() !== 'POST' || !r.url().includes('/functions/v1/start-voice-session')) return;
    try {
      attemptIds.push(String((r.postDataJSON() as { attempt_id?: string })?.attempt_id || ''));
    } catch {
      attemptIds.push('');
    }
  });
}

/** Ждёт POST start-voice-session (оборванный → requestfailed, настоящий → response). */
function waitVoiceRequest(page: Page) {
  return page.waitForRequest((r) => r.url().includes('/functions/v1/start-voice-session') && r.method() === 'POST');
}

/** Сетевое сообщение: data-reason=network, точный текст, «נסו שוב» + «לפנות לצוות לעזרה», не «בצד שלנו». */
async function expectNetworkFailure(page: Page) {
  const failure = page.getByTestId('start-failure');
  await expect(failure).toBeVisible({ timeout: 15_000 });
  await expect(failure).toHaveAttribute('data-reason', 'network');
  await expect(failure.getByRole('alert')).toHaveText(NETWORK_FAIL);
  await expect(failure.getByRole('button', { name: TXT.retry })).toBeVisible();
  await expect(failure.getByRole('button', { name: TXT.help })).toBeVisible();
  await expect(failure).not.toContainText('בצד שלנו');
}

test.afterAll(async () => {
  await cand?.browser.close();
});

test.describe('Звонок кандидата — повтор старта официального звонка на той же попытке (#d9aa30282ea83831ce4afdeb) @call', () => {
  test('start-voice-session оборван после старта попытки → сетевое сообщение, «נסו שוב», путь к команде; 1 старт попытки @desktop @data #d9aa30282ea83831ce4afdeb', async ({ asUser }) => {
    test.setTimeout(5 * 60_000);
    const business = await asUser('business');
    name = `QA-AUTO-CALL-S-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}», не удаляется` });

    cand = await launchCandidate({ width: 390, height: 844 });
    const { page, counts } = cand;
    trackAttemptIds(page);
    await goToPractice(page, link);
    await goToOfficialConfirm(page);

    await dropVoiceSession(page);
    const start = page.waitForResponse((r) => r.url().includes('/rpc/candidate_start_attempt') && r.request().method() === 'POST');
    const voice = waitVoiceRequest(page);
    await tap(page, 'מוכן, מתחילים');
    expect((await start).status(), 'candidate_start_attempt — настоящий').toBe(200);
    await voice;

    // Источник: комментарий программиста к #da072b — «תקלת רשת אמיתית … ממשיכה להציג את הודעת האינטרנט, והניסיון נשאר פתוח»; CALL-033.
    await expectNetworkFailure(page);
    expect(counts.start, 'candidate_start_attempt на одно нажатие').toBe(1);
    expect(counts.voice, 'start-voice-session на одно нажатие').toBe(1);
    expect(attemptIds[0], 'start-voice-session несёт attempt_id').not.toBe('');

    // Источник: «מצב נדרש» #d9aa30 — «נתיב פנייה».
    await expectHelpPath(page, /כנראה בגלל תקלה בחיבור לאינטרנט/);
  });

  test('сбой продолжается: «נסו שוב» → та же попытка (тот же attempt_id), нового старта нет; у бизнеса «בתהליך», не «תקלה טכנית»/«הושלמה» @desktop @data #d9aa30282ea83831ce4afdeb', async ({ asUser }) => {
    expect(cand, 'нет состояния из первого теста').toBeTruthy();
    const { page, counts } = cand!;

    const voice = waitVoiceRequest(page);
    await tap(page, TXT.retry);
    await voice;
    await expectNetworkFailure(page);
    expect(counts.voice).toBe(2);
    expect(counts.start, 'повтор не создаёт новую попытку (candidate_start_attempt)').toBe(1);
    expect(attemptIds[1], 'повтор идёт на той же попытке').toBe(attemptIds[0]);

    // Попытка не закрыта у бизнеса (CALL-033: in_progress держится 30 с).
    const business = await asUser('business');
    const row = await candidateRow(business, name);
    await expect(row).toContainText('בתהליך');
    for (const bad of ['תקלה טכנית', 'הושלמה']) await expect(row).not.toContainText(bad);
  });

  test('сеть вернулась (обрыв снят) → «נסו שוב»: звонок на той же попытке; «הסימולציה הושלמה» @desktop @data @slow #d9aa30282ea83831ce4afdeb', async () => {
    test.setTimeout(6 * 60_000);
    expect(cand, 'нет состояния из первого теста').toBeTruthy();
    const { page, counts } = cand!;
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: официальная попытка использована` });

    await page.unroute(VOICE);
    const hint = waitConnectingHint(page);
    const voice = page.waitForResponse((r) => r.url().includes('/functions/v1/start-voice-session') && r.request().method() === 'POST');
    await tap(page, TXT.retry);
    expect((await voice).status(), 'настоящий start-voice-session после снятия обрыва').toBe(200);
    expect(await hint).toBe(TXT.hint);

    await expect(page.getByText('הניסיון הרשמי')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible();
    await expect(page.getByTestId('start-failure')).toHaveCount(0);
    expect(counts.voice).toBe(3);
    expect(counts.start, 'официальная попытка та же — candidate_start_attempt не добавился').toBe(1);
    expect(attemptIds[2]).toBe(attemptIds[0]);

    await tap(page, 'לסיים שיחה');
    await tap(page, 'לאשר סיום שיחה');
    await expect(page.getByText('הסימולציה הושלמה')).toBeVisible({ timeout: 60_000 });
  });
});
